export const items = data.map(([category,group,name,description,price],index)=>({id:`item-${index+1}`,category,group,name,description,price}));
export const priceFor = (item,size=1) => Array.isArray(item.price) ? item.price[size] : item.price;
export const normalize = text => text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
export const findItems = query => items.filter(item=>normalize(`${item.name} ${item.description} ${item.group} ${item.category}`).includes(normalize(query)));
export const currency = value => '$' + new Intl.NumberFormat('es-CO').format(value);
